function addMessage(kind,name,text,meta=''){const welcome=$('welcome');if(welcome)welcome.remove();const box=el('article','msg '+kind);const head=el('div','msg-head');head.append(el('strong','',name),el('span','meta',meta));const body=el('div','msg-body',text);body.dir='auto';box.append(head,body);$('messages').append(box);$('messages').scrollTop=$('messages').scrollHeight;return box;}
function setBusy(v,label='در حال دریافت پاسخ…'){busy=v;$('send').disabled=v;$('input').disabled=v;$('status').textContent=v?label:'آمادهٔ گفتگو';if(v){$('send').textContent='منتظر…';}else{$('send').textContent='ارسال';}}
async function sendMessage(){if(busy)return;const text=$('input').value.trim();if(!text)return;$('input').value='';if(!title){title=text.slice(0,55);$('chatTitle').textContent=title;}transcript.push({kind:'user',text,at:new Date().toISOString()});addMessage('user','تو',text);setBusy(true);const startedAt=Date.now();const pending=addMessage('','سالوون','در حال دریافت پاسخ اعضا… (۰ ثانیه)');const waitTimer=setInterval(()=>{const seconds=Math.floor((Date.now()-startedAt)/1000);pending.querySelector('.msg-body').textContent='در حال دریافت پاسخ اعضا… ('+seconds+' ثانیه)';$('status').textContent='در انتظار پاسخ اعضا: '+seconds+' ثانیه';},1000);try{const r=await api('/api/chat',{text,transcript});pending.remove();for(const item of r.events){transcript.push(item);if(item.kind==='reply')addMessage('',''+item.member,item.text,item.model);else if(item.kind==='error')addMessage('error','خطا: '+item.member,item.text);}if(r.saved)$('status').textContent='ذخیره شد: '+r.saved.split(/[\\/]/).pop();}catch(e){pending.remove();addMessage('error','خطای سالوون',e.message);}finally{clearInterval(waitTimer);setBusy(false);$('input').focus();}}
