        role="نقش تو: تحلیل‌گر مستقل. واقعیت، فرض، استنتاج و پرسش‌های باز را از هم جدا کن. از تقلید اعضای دیگر پرهیز کن. به فارسی پاسخ بده مگر کاربر زبان دیگری بخواهد.",
    ),
]


def load_members() -> list[Member]:
    if not CONFIG_PATH.exists():
        save_members(DEFAULT_MEMBERS)
        return [Member(**asdict(m)) for m in DEFAULT_MEMBERS]
    raw = json.loads(CONFIG_PATH.read_text(encoding="utf-8"))
    return [Member(**item) for item in raw]


def save_members(members: list[Member]) -> None:
    CONFIG_PATH.write_text(
        json.dumps([asdict(m) for m in members], ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
    )


def call_model(api_key: str, member: Member, transcript: list[dict[str, Any]]) -> tuple[str, bool]:
    messages: list[dict[str, str]] = []
    for item in transcript[-MAX_HISTORY_MESSAGES:]:
        if item["kind"] == "user":
            messages.append({"role": "user", "content": item["text"]})
        elif item["kind"] == "reply":
            messages.append({
                "role": "assistant",
                "content": "[" + item["member"] + "]: " + item["text"],
            })
        elif item["kind"] == "error":
            messages.append({
                "role": "user",
                "content": "[اطلاع فنی: پاسخ عضو " + item.get("member", "نامشخص")
                + " ناموفق بود: " + item["text"] + "]",
            })
    messages.append({
        "role": "user",
        "content": (
            "تو عضو «" + member.name + "» در یک گفت‌وگوی گروهی هستی. "
            "به آخرین پیام کاربر یا ادعای مرتبط پاسخ بده. "
            "اگر با عضوی اختلاف داری، ادعای مشخص او را منصفانه بازگو کن. "
            "اختلاف موجه را حفظ کن و کل گفتگو را از ابتدا تکرار نکن."
        ),
    })
    payload = {
        "model": member.model,
        "messages": [{"role": "system", "content": member.role + "\n\nزبان پیش‌فرض گفتگو فارسی است. به فارسی روان و طبیعی پاسخ بده، مگر اینکه کاربر صریحاً زبان دیگری بخواهد. متن‌های انگلیسی، نام مدل‌ها و کدها را در صورت نیاز به شکل اصلی نگه دار."}, *messages],
        "temperature": member.temperature,
        "max_tokens": member.max_tokens,
    }
    # The Dots3 model supports OpenRouter's reasoning controls. Cap reasoning separately
    # so it cannot consume the entire completion budget before producing user-facing text.
    if member.model == "dots-studio/dots-3-note-preview:free":
        payload["reasoning"] = {"max_tokens": 256, "exclude": True}
    req = urllib.request.Request(
        API_URL,
        data=json.dumps(payload, ensure_ascii=False).encode("utf-8"),
        headers={
            "Authorization": "Bearer " + api_key,
            "Content-Type": "application/json; charset=utf-8",
            "HTTP-Referer": "http://localhost/saloon-chat",
            "X-Title": "Saloon Web v4",
        },
        method="POST",
    )
    http_status = None
    try:
        with urllib.request.urlopen(req, timeout=120) as response:
            http_status = response.status
            data = json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        detail = exc.read().decode("utf-8", errors="replace")[:1000]
        raise RuntimeError("HTTP " + str(exc.code) + ": " + detail) from exc
    except (urllib.error.URLError, TimeoutError, json.JSONDecodeError, OSError, http.client.HTTPException) as exc:
        # urllib may surface connection resets and incomplete reads as raw OSError/
        # HTTPException instances rather than wrapping every failure in URLError.
        raise RuntimeError("خطای ارتباط با سرویس: " + str(exc)) from exc

    choices = data.get("choices") or []
    if not choices:
        raise RuntimeError("سرویس پاسخی برنگرداند: " + json.dumps(data, ensure_ascii=False)[:700])
    choice = choices[0]
    message = choice.get("message") or {}
    value = message.get("content")
    if isinstance(value, list):
        value = "\n".join(str(part.get("text", "")) for part in value if isinstance(part, dict))
    answer = str(value or "").strip()
    finish_reason = choice.get("finish_reason", "unknown")
    truncated = finish_reason == "length"

    # Diagnostic logging for empty/truncated responses. Never log request headers or API key.
    if not answer or truncated:
        print("\n[diagnostic] OpenRouter response for member: " + member.name)
        print("[diagnostic] HTTP status: " + str(http_status))
        print("[diagnostic] requested model: " + member.model)
        print("[diagnostic] returned model: " + str(data.get("model", "unknown")))
        print("[diagnostic] usage: " + json.dumps(data.get("usage"), ensure_ascii=False))
        print("[diagnostic] finish_reason: " + str(finish_reason))
        print("[diagnostic] message fields: " + ", ".join(sorted(message.keys())))
        print("[diagnostic] content type: " + type(value).__name__)
        print("[diagnostic] content length: " + str(len(answer)))
        reasoning = message.get("reasoning")
        print("[diagnostic] reasoning present/length: " + str(bool(reasoning)) + "/" + str(len(str(reasoning or ""))))
        # Do not print raw reasoning or message content.

    if not answer:
        raise RuntimeError("پاسخ خالی بود (finish_reason=" + str(finish_reason) + "). جزئیات تشخیصی در پنجرهٔ PowerShell ثبت شد.")
    return answer, truncated



def collect_member_events(
    api_key: str,
    members: list[Member],
    transcript: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """Run each selected member independently and retain every result."""
    context = list(transcript)
    events: list[dict[str, Any]] = []
    for member in members:
        try:
            answer, truncated = call_model(api_key, member, context)
            if truncated:
                answer += "\n\n[هشدار: احتمال دارد پاسخ به‌دلیل رسیدن به سقف توکن ناقص باشد.]"
            event = {
                "kind": "reply",
                "member": member.name,
                "model": member.model,
                "text": answer,
                "at": time.strftime("%Y-%m-%dT%H:%M:%S"),
            }
        except Exception as exc:
            # A failed member must not discard earlier replies or block later members.
            print("[member-error] " + member.name + ": " + type(exc).__name__ + ": " + str(exc))
            event = {
                "kind": "error",
                "member": member.name,
                "text": str(exc) or type(exc).__name__,
                "at": time.strftime("%Y-%m-%dT%H:%M:%S"),
            }
        events.append(event)
        context.append(event)
    return events, context

def resolve_recipients(text: str, members: list[Member]) -> list[Member]:
    """Resolve explicit @mentions; without mentions, use every enabled member.

    Supported forms: @Analyst and @"Member Name".
    Unknown, duplicate-name, or disabled targets fail closed rather than
    silently falling back to the group.
    """
    mentions = re.findall(r'(?<![\w@])@(?:"([^"]+)"|([\w.-]+))', text)
    active = [member for member in members if member.enabled]
    if not mentions:
        return active

    selected: list[Member] = []
    seen: set[int] = set()
    for quoted, plain in mentions:
        requested = (quoted or plain).strip()
        matches = [m for m in members if m.name.casefold() == requested.casefold()]
        if not matches:
            raise ValueError("مخاطب ناشناخته: @" + requested + " — نام عضو را دقیق بررسی کن.")
        if len(matches) > 1:
            raise ValueError("نام مخاطب تکراری و مبهم است: @" + requested + " — نام اعضا باید یکتا باشد.")
        member = matches[0]
        if not member.enabled:
            raise ValueError("عضو مخاطب غیرفعال است: @" + member.name)
        identity = id(member)
        if identity not in seen:
            selected.append(member)
            seen.add(identity)
    # Keep the configured member order, independent of mention order.
    return [member for member in members if id(member) in seen]


def save_transcript(transcript: list[dict[str, Any]]) -> str:
    LOG_DIR.mkdir(parents=True, exist_ok=True)
    stamp = time.strftime("%Y%m%d_%H%M%S")
    path = LOG_DIR / ("saloon_web_" + stamp + ".json")
    # Avoid overwriting if two saves occur in the same second.
    suffix = 1
    while path.exists():
        path = LOG_DIR / ("saloon_web_" + stamp + "_" + str(suffix) + ".json")
        suffix += 1
    path.write_text(json.dumps(transcript, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return str(path)


